from typing import TypedDict

# type of the PSM transition
# the value "from" is Python keywords, so using this type to define the transition
TransitionRecord = TypedDict(
    "TransitionRecord",
    {
        "from": str,
        "event": str,
        "action": str,
        "to": str
    }
)

# protocol state machine
class StateMachine(TypedDict):
    states: list[str]
    initial_state: str
    final_states: list[str]
    transitions: list[TransitionRecord]


# Store evaluation counts and scores.
class MetricResult(TypedDict):
    # the number of items generated by the model
    llm_predicted_count: int

    # the number of items of reference PSM
    ground_truth_count: int

    matched_count: int
    missing_count: int
    extra_count: int


    # The percentage of generated items that are correct.
    precision: float
    # The percentage of reference items found by the model.
    recall: float
    # The combined score of Precision and Recall.
    f1: float


# final result of PSM
class EvaluationResult(TypedDict):
    # if the model output was read successfully.
    parsed: bool

    # if the PSM structure is correct.
    structure_valid: bool

    # The structure problems found in the PSM.
    structure_errors: list[str]

    # The state evaluation result.
    states: MetricResult
    # The complete transition evaluation result.
    exact_transitions: MetricResult
    # The partial transition evaluation result.
    partial_transitions: MetricResult




